import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'app-dictation',
  templateUrl: './dictation.component.html',
  styleUrls: ['./dictation.component.scss']
})
export class DictationComponent implements OnInit {

  lessons = [
    { title: 'درس ۱: آب، باران', words: ['آب', 'بابا', 'بادام', 'باران', 'نان'] },
    { title: 'درس ۲: ابر، باد', words: ['باد', 'ابر', 'مادر', 'دامان', 'انار'] },
    { title: 'درس ۳: مدرسه ما', words: ['مدرسه', 'کلاس', 'کتاب', 'درس', 'دوست'] },
    { title: 'درس ۴: ایران زیبا', words: ['ایران', 'آزادی', 'پرچم', 'سرسبز', 'میهن'] }
  ];

  selectedLessonIndex = 0;
  customWord = '';
  wordsList: string[] = [];

  currentIndex = 0;
  isReading = false;
  readInterval: any = null;

  ngOnInit(): void {
    this.selectLesson(0);
  }

  selectLesson(idx: number): void {
    this.selectedLessonIndex = idx;
    this.wordsList = [...this.lessons[idx].words];
    this.currentIndex = 0;
  }

  addWord(): void {
    if (this.customWord && this.customWord.trim()) {
      this.wordsList.push(this.customWord.trim());
      this.customWord = '';
    }
  }

  removeWord(i: number): void {
    this.wordsList.splice(i, 1);
  }

  speakCurrentWord(): void {
    if (this.wordsList.length === 0) { return; }
    const word = this.wordsList[this.currentIndex];
    if ('speechSynthesis' in window) {
      const u = new SpeechSynthesisUtterance(word);
      u.lang = 'fa-IR';
      u.rate = 0.8; // آهسته برای نوشتن کودک
      window.speechSynthesis.speak(u);
    }
  }

  nextWord(): void {
    if (this.currentIndex < this.wordsList.length - 1) {
      this.currentIndex++;
      this.speakCurrentWord();
    }
  }

  prevWord(): void {
    if (this.currentIndex > 0) {
      this.currentIndex--;
      this.speakCurrentWord();
    }
  }
}
